import{_ as i,o as a,c as e,a6 as t}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"完整建设目录","description":"","frontmatter":{"id":"outline","title":"完整建设目录","chapter":"00","status":"已公开","evidence_status":"目录已规划","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":1},"headers":[],"relativePath":"outline.md","filePath":"outline.md"}'),r={name:"outline.md"};function o(h,l,n,d,u,s){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="完整建设目录-14章" tabindex="-1">完整建设目录（14章） <a class="header-anchor" href="#完整建设目录-14章" aria-label="Permalink to &quot;完整建设目录（14章）&quot;">​</a></h1><p>这份目录定义完整建设范围。已有方法与模板可从侧栏进入；未关联正文的条目仍待补，不表示教程已完成。</p><p>电商是最大应用专题，其他视觉创作独立成章。共用方法集中讲一次，再由具体任务引用；工具与模型作为实现路径，不用型号名称决定整个知识库的目录。</p><h2 id="总目录" tabindex="-1">总目录 <a class="header-anchor" href="#总目录" aria-label="Permalink to &quot;总目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>章节</th><th>主要解决的问题</th></tr></thead><tbody><tr><td>第一部分：共用基础</td><td>00 开始使用；01 通用作图与修图；02 提示词与参考素材</td><td>从输入素材到第一张可用图，理解怎么描述、修改和检查</td></tr><tr><td>第二部分：应用专题</td><td>03 电商；04 品牌包装广告；05 内容与出版；06 人物服装IP；07 摄影空间；08 信息图演示UI；09 插画创意；10 视频动态</td><td>按实际要交付的作品找教程，电商展开最细</td></tr><tr><td>第三部分：制作流程</td><td>11 三类画布；12 Codex与批量自动化</td><td>组织项目、精修图层、复用工作流、完成系列交付</td></tr><tr><td>第四部分：资料库</td><td>13 提示词、案例、工具与开源仓库</td><td>快速找完整模板、案例、工具、仓库与更新记录</td></tr></tbody></table><h2 id="_00-开始使用与学习路线" tabindex="-1">00 开始使用与学习路线 <a class="header-anchor" href="#_00-开始使用与学习路线" aria-label="Permalink to &quot;00 开始使用与学习路线&quot;">​</a></h2><ul><li>00.1 按任务找入口：商品图、品牌物料、内容配图、人物、信息图、短片</li><li>00.2 输入素材清单：照片、参考图、Logo、文案、表格、视频、草图</li><li>00.3 素材分别起什么作用：真实对象、风格、布局、背景与已确认文字</li><li>00.4 模型、网站工具、设计画布、插件、API与本地软件的区别</li><li>00.5 第一张可用图：准备素材 → 生成 → 检查 → 局部修改 → 导出</li><li>00.6 基础文件知识：比例、像素、裁切、透明背景、色彩与文件格式</li><li>00.7 三条阅读路线：第一次作图／已有图要修改／整套图片要交付</li><li>00.8 怎样使用教程、完整提示词、结果图与源文件</li></ul><h2 id="_01-通用作图与修图方法" tabindex="-1">01 通用作图与修图方法 <a class="header-anchor" href="#_01-通用作图与修图方法" aria-label="Permalink to &quot;01 通用作图与修图方法&quot;">​</a></h2><ul><li>01.1 文生图：主体、环境、构图、光线、材质与风格</li><li>01.2 图生图：保留哪些内容，允许改变哪些内容</li><li>01.3 多参考图：对象、布局与风格分别引用</li><li>01.4 草图、色块、标注与位置描述控制画面</li><li>01.5 换背景、替换对象、合成与光影融合</li><li>01.6 局部修改：蒙版、选择区、修改范围与边缘衔接</li><li>01.7 抠图、消除、扩图、修瑕、降噪、放大与照片修复</li><li>01.8 文字与Logo：生成、逐字检查、独立排版与后期替换</li><li>01.9 系列一致性：对象、风格、色彩、版式与多尺寸延展</li><li>01.10 常见失败排查：主体变形、属性漂移、文字错误与构图失控</li><li>01.11 交付检查：真实内容、清晰度、边缘、文字、裁切与文件</li></ul><h2 id="_02-提示词与参考素材" tabindex="-1">02 提示词与参考素材 <a class="header-anchor" href="#_02-提示词与参考素材" aria-label="Permalink to &quot;02 提示词与参考素材&quot;">​</a></h2><ul><li>02.1 一条完整提示词的结构：任务、输入、约束、画面与输出</li><li>02.2 六类用途：分析、策划、生图、修图、排版、批量工作流</li><li>02.3 中文与英文提示词：什么时候需要改写或本地化</li><li>02.4 参考图的角色说明：哪些必须保持，哪些只借鉴风格</li><li>02.5 商品、人物、Logo与文字的保持要求怎么写</li><li>02.6 复杂任务拆步骤：先分析素材，再规划，再生成和修改</li><li>02.7 从一句短词到可执行模板：补输入、变量、示例与输出要求</li><li>02.8 模型与工具适配：同一任务的不同写法与实际参数</li><li>02.9 失败后怎么改词：改变一个关键条件并比较结果</li><li>02.10 提示词如何入库：完整正文、适用任务、输入示例与结果状态</li></ul><h2 id="_03-电商视觉实战-最大专题" tabindex="-1">03 电商视觉实战（最大专题） <a class="header-anchor" href="#_03-电商视觉实战-最大专题" aria-label="Permalink to &quot;03 电商视觉实战（最大专题）&quot;">​</a></h2><h3 id="_03-1-商品资料与出图规划" tabindex="-1">03.1 商品资料与出图规划 <a class="header-anchor" href="#_03-1-商品资料与出图规划" aria-label="Permalink to &quot;03.1 商品资料与出图规划&quot;">​</a></h3><ul><li>03.1.1 商品事实表：规格、材质、功能、包装、配件与未知信息</li><li>03.1.2 产品照片、竞品参考、品牌素材与已确认文案</li><li>03.1.3 用户、使用场景、卖点与一套图片的阅读顺序</li><li>03.1.4 主图、副图、详情页、A+与广告素材的任务分工</li></ul><h3 id="_03-2-单张商品图的基础制作" tabindex="-1">03.2 单张商品图的基础制作 <a class="header-anchor" href="#_03-2-单张商品图的基础制作" aria-label="Permalink to &quot;03.2 单张商品图的基础制作&quot;">​</a></h3><ul><li>03.2.1 白底图、抠图、阴影与真实商品精修</li><li>03.2.2 场景图、生活方式图与使用情境</li><li>03.2.3 材质、结构、细节、透明与反光难例</li><li>03.2.4 尺寸、规格、包装、配件与使用步骤图</li><li>03.2.5 卖点、对比与信任信息的视觉表达</li></ul><h3 id="_03-3-从单张到整套图片" tabindex="-1">03.3 从单张到整套图片 <a class="header-anchor" href="#_03-3-从单张到整套图片" aria-label="Permalink to &quot;03.3 从单张到整套图片&quot;">​</a></h3><ul><li>03.3.1 主图定位与首图的三个信息层级</li><li>03.3.2 主图＋副图套图的角色与顺序</li><li>03.3.3 详情页：首屏、卖点、使用、细节、规格与答疑</li><li>03.3.4 从一张产品照片完成一套图片的完整流程</li><li>03.3.5 长图、模块图与移动端阅读检查</li></ul><h3 id="_03-4-国内电商适配" tabindex="-1">03.4 国内电商适配 <a class="header-anchor" href="#_03-4-国内电商适配" aria-label="Permalink to &quot;03.4 国内电商适配&quot;">​</a></h3><ul><li>03.4.1 淘宝／天猫：主图、副图、详情页与活动素材</li><li>03.4.2 京东／拼多多：按用途和类目组织图片</li><li>03.4.3 国内平台素材复用与不同尺寸的改版</li></ul><h3 id="_03-5-跨境电商适配" tabindex="-1">03.5 跨境电商适配 <a class="header-anchor" href="#_03-5-跨境电商适配" aria-label="Permalink to &quot;03.5 跨境电商适配&quot;">​</a></h3><ul><li>03.5.1 <a href="/ai-visual-creation-handbook/ecommerce/amazon-listing">Amazon主图与副图：产品展示、场景、尺寸、功能与配件</a></li><li>03.5.2 <a href="/ai-visual-creation-handbook/ecommerce/amazon-a-plus">Amazon Basic A+／Premium A+：模块规划与素材衔接</a></li><li>03.5.3 Amazon Brand Story：品牌故事、系列与产品关联</li><li>03.5.4 Shopify：<a href="/ai-visual-creation-handbook/ecommerce/shopify-product">产品页与集合媒体</a>、<a href="/ai-visual-creation-handbook/ecommerce/shopify-hero">首页Banner与手机裁切</a></li><li>03.5.5 <a href="/ai-visual-creation-handbook/ecommerce/shopee-localization">Shopee SG：站点语言、卖点、规格与变体素材</a>；Lazada专篇待补</li><li>03.5.6 TikTok Shop：商品图、内容封面与视频素材的衔接</li><li>03.5.7 AliExpress／eBay等：按实际平台任务补充</li><li>03.5.8 平台图片要求：站点、用途、类目与更新时间分开记录</li></ul><h3 id="_03-6-品类专项" tabindex="-1">03.6 品类专项 <a class="header-anchor" href="#_03-6-品类专项" aria-label="Permalink to &quot;03.6 品类专项&quot;">​</a></h3><ul><li>03.6.1 食品与饮料：食用场景、包装、质感与真实成分信息</li><li>03.6.2 美妆与个护：瓶罐、质地、使用场景与包装细节</li><li>03.6.3 宠物、家居、小家电与数码：结构、功能、比例与配件</li><li>03.6.4 服装、鞋包、饰品：模特、搭配、角度与款式保持</li><li>03.6.5 特殊材质：玻璃、金属、透明、毛发、纹理与花型</li></ul><h3 id="_03-7-本地化、变体与系列生产" tabindex="-1">03.7 本地化、变体与系列生产 <a class="header-anchor" href="#_03-7-本地化、变体与系列生产" aria-label="Permalink to &quot;03.7 本地化、变体与系列生产&quot;">​</a></h3><ul><li>03.7.1 多语言文案、表达习惯、尺寸单位与图中文字检查</li><li>03.7.2 SKU、颜色、花型、包装和组合装的一致性</li><li>03.7.3 节日、大促、广告、邮件与社交素材延展</li><li>03.7.4 多平台、多语言、多尺寸的出图任务表与检查</li></ul><h3 id="_03-8-电商完整案例库" tabindex="-1">03.8 电商完整案例库 <a class="header-anchor" href="#_03-8-电商完整案例库" aria-label="Permalink to &quot;03.8 电商完整案例库&quot;">​</a></h3><ul><li>03.8.1 一张产品图 → 国内主图套图＋详情页</li><li>03.8.2 同一商品 → Amazon副图＋A+＋品牌故事</li><li>03.8.3 同一商品 → Shopify页面＋跨站点本地化素材</li><li>03.8.4 同一任务 → 设计画布、节点工作流、图层精修三条路径</li><li>03.8.5 案例结构：原始素材、规划、完整提示词、过程、结果与失败修改</li></ul><h2 id="_04-品牌、包装与广告设计" tabindex="-1">04 品牌、包装与广告设计 <a class="header-anchor" href="#_04-品牌、包装与广告设计" aria-label="Permalink to &quot;04 品牌、包装与广告设计&quot;">​</a></h2><ul><li>04.1 品牌简报：受众、定位、视觉方向与已有素材</li><li>04.2 Logo探索、品牌色、字体与图形语言</li><li>04.3 品牌VI延展：名片、标签、头像与常用物料</li><li>04.4 包装视觉、标签、样机与真实刀模的配合</li><li>04.5 品牌主视觉KV、发布海报与活动物料</li><li>04.6 门店、菜单、展架、传单与线下展示</li><li>04.7 同一活动的多尺寸、多语言与系列延展</li><li>04.8 屏幕视觉稿、可编辑设计与印刷交付</li></ul><h2 id="_05-内容传播与出版配图" tabindex="-1">05 内容传播与出版配图 <a class="header-anchor" href="#_05-内容传播与出版配图" aria-label="Permalink to &quot;05 内容传播与出版配图&quot;">​</a></h2><ul><li>05.1 公众号封面、首图、章节图与正文插图</li><li>05.2 小红书封面、知识卡片与系列图文</li><li>05.3 抖音／TikTok／B站／YouTube封面与静态物料</li><li>05.4 文章、教程、长帖与新闻解读配图</li><li>05.5 书封、杂志、报告封面与出版插图</li><li>05.6 招募、活动、课程与信息海报</li><li>05.7 内容系列的统一视觉、可编辑文字与多尺寸改版</li></ul><h2 id="_06-人物、服装与ip" tabindex="-1">06 人物、服装与IP <a class="header-anchor" href="#_06-人物、服装与ip" aria-label="Permalink to &quot;06 人物、服装与IP&quot;">​</a></h2><ul><li>06.1 人物写真、头像与形象照</li><li>06.2 虚构角色、品牌吉祥物与IP设定</li><li>06.3 人物身份、服装、发型与姿势的一致性</li><li>06.4 服装搭配、展示、模特与虚拟试穿</li><li>06.5 多视角、表情、动作与角色设定表</li><li>06.6 从人物图到系列海报、故事场景与视频关键帧</li><li>06.7 人物与服装细节的检查和局部修正</li></ul><h2 id="_07-摄影、场景与空间" tabindex="-1">07 摄影、场景与空间 <a class="header-anchor" href="#_07-摄影、场景与空间" aria-label="Permalink to &quot;07 摄影、场景与空间&quot;">​</a></h2><ul><li>07.1 光线、镜头、景别、景深与摄影真实感</li><li>07.2 食物、静物、生活方式与主题摄影</li><li>07.3 原照片修复、重打光、合成与背景调整</li><li>07.4 家居、室内、建筑、园林与陈列概念图</li><li>07.5 空间比例、透视、遮挡与物体放置</li><li>07.6 摄影素材到画布合成与图层精修</li></ul><h2 id="_08-信息图、教学、演示与ui视觉" tabindex="-1">08 信息图、教学、演示与UI视觉 <a class="header-anchor" href="#_08-信息图、教学、演示与ui视觉" aria-label="Permalink to &quot;08 信息图、教学、演示与UI视觉&quot;">​</a></h2><ul><li>08.1 原始材料到知识卡片：信息选择与层级</li><li>08.2 流程图、结构图、步骤图与关系图</li><li>08.3 数据图表：真实数据、准确图形与视觉装饰</li><li>08.4 教学、科普、研究与报告示意图</li><li>08.5 PPT视觉稿、页面排版与可编辑演示文件</li><li>08.6 网站／App界面视觉稿、图标、插图与组件素材</li><li>08.7 大量文字和复杂版式的独立排版</li></ul><h2 id="_09-插画、漫画与创意探索" tabindex="-1">09 插画、漫画与创意探索 <a class="header-anchor" href="#_09-插画、漫画与创意探索" aria-label="Permalink to &quot;09 插画、漫画与创意探索&quot;">​</a></h2><ul><li>09.1 插画、漫画、绘本与故事场景</li><li>09.2 国风、复古、艺术与风格实验</li><li>09.3 游戏、影视与3D风格的概念图和素材</li><li>09.4 材质、纹样、贴纸与装饰图形</li><li>09.5 角色、场景与分镜系列的一致性</li><li>09.6 创意发散、方案比较、选稿与继续修改</li></ul><h2 id="_10-短视频与动态视觉" tabindex="-1">10 短视频与动态视觉 <a class="header-anchor" href="#_10-短视频与动态视觉" aria-label="Permalink to &quot;10 短视频与动态视觉&quot;">​</a></h2><ul><li>10.1 产品、品牌、人物与内容短片的目标和素材</li><li>10.2 参考视频拆解：结构、镜头、节奏与字幕</li><li>10.3 脚本、分镜、关键帧与镜头连续性</li><li>10.4 图生视频、首尾帧、参考视频与具体工具适配</li><li>10.5 运镜、主体动作、材质与场景变化</li><li>10.6 产品、服装、人物和品牌短片流程</li><li>10.7 动态海报、简单动效与剪辑衔接</li><li>10.8 声音、字幕、配乐、节奏与最终导出</li><li>10.9 变形、闪烁、身份漂移与失败重做</li></ul><h2 id="_11-三类画布与制作工作流" tabindex="-1">11 三类画布与制作工作流 <a class="header-anchor" href="#_11-三类画布与制作工作流" aria-label="Permalink to &quot;11 三类画布与制作工作流&quot;">​</a></h2><h3 id="_11-1-共用项目组织" tabindex="-1">11.1 共用项目组织 <a class="header-anchor" href="#_11-1-共用项目组织" aria-label="Permalink to &quot;11.1 共用项目组织&quot;">​</a></h3><ul><li>11.1.1 参考板、素材身份、文案、任务分区与输出清单</li><li>11.1.2 方案分支、局部修改、系列延展与版本比较</li><li>11.1.3 从创意探索到可交付文件的完整路径</li></ul><h3 id="_11-2-ai设计与内容画布" tabindex="-1">11.2 AI设计与内容画布 <a class="header-anchor" href="#_11-2-ai设计与内容画布" aria-label="Permalink to &quot;11.2 AI设计与内容画布&quot;">​</a></h3><ul><li>11.2.1 Lovart／TapNow等工具：参考、生成、修改与素材组织</li><li>11.2.2 多张图片、多个页面与同一项目的整体一致性</li><li>11.2.3 电商套图、品牌活动、内容系列的画布实例</li><li>11.2.4 画布成品的文字、尺寸、裁切与导出检查</li></ul><h3 id="_11-3-comfyui节点工作流" tabindex="-1">11.3 ComfyUI节点工作流 <a class="header-anchor" href="#_11-3-comfyui节点工作流" aria-label="Permalink to &quot;11.3 ComfyUI节点工作流&quot;">​</a></h3><ul><li>11.3.1 图像、蒙版、模型、条件、采样与输出的关系</li><li>11.3.2 商品保持、背景替换、局部修图与放大流程</li><li>11.3.3 多SKU、多尺寸与批量任务的节点组织</li><li>11.3.4 工作流文件、模型、节点依赖与复用说明</li><li>11.3.5 报错、缺节点、缺模型与版本变化的排查</li></ul><h3 id="_11-4-ps-krita等图层精修" tabindex="-1">11.4 PS／Krita等图层精修 <a class="header-anchor" href="#_11-4-ps-krita等图层精修" aria-label="Permalink to &quot;11.4 PS／Krita等图层精修&quot;">​</a></h3><ul><li>11.4.1 图层、蒙版、选择区、文字与智能对象</li><li>11.4.2 商品边缘、材质、Logo、文字与局部细节精修</li><li>11.4.3 生成图片到可编辑文件：拆分、合成、排版与保存</li><li>11.4.4 PSD、透明PNG、矢量素材与成品图的交付检查</li></ul><h3 id="_11-5-同一任务的三条制作路径" tabindex="-1">11.5 同一任务的三条制作路径 <a class="header-anchor" href="#_11-5-同一任务的三条制作路径" aria-label="Permalink to &quot;11.5 同一任务的三条制作路径&quot;">​</a></h3><ul><li>11.5.1 电商套图：设计画布 → 节点复用 → 图层精修</li><li>11.5.2 品牌与内容：方案探索 → 系列延展 → 文字和细节整理</li><li>11.5.3 三条路径如何组合，在哪一步转入另一种工具</li></ul><h2 id="_12-codex与批量自动化" tabindex="-1">12 Codex与批量自动化 <a class="header-anchor" href="#_12-codex与批量自动化" aria-label="Permalink to &quot;12 Codex与批量自动化&quot;">​</a></h2><ul><li>12.1 Codex在视觉项目中的任务：读素材、写脚本、组织文件与调用工具</li><li>12.2 Codex操作PS作图修图：连接方式、实际可用操作与任务边界</li><li>12.3 PS任务实例：替换文案、调整画布、套模板、整理图层与批量导出</li><li>12.4 图片批处理：改尺寸、命名、裁切、格式转换与预览联系表</li><li>12.5 按SKU、语言、平台与尺寸生成任务矩阵</li><li>12.6 API与本地工作流：输入、输出、失败记录与继续处理</li><li>12.7 自动处理与人工检查的衔接</li><li>12.8 原图、项目文件、生成结果与最终交付的目录组织</li><li>12.9 从作图流程到业务Skill：输入、职责分工、步骤、检查与交付</li></ul><h2 id="_13-提示词、案例、工具与开源仓库" tabindex="-1">13 提示词、案例、工具与开源仓库 <a class="header-anchor" href="#_13-提示词、案例、工具与开源仓库" aria-label="Permalink to &quot;13 提示词、案例、工具与开源仓库&quot;">​</a></h2><h3 id="_13-1-完整提示词库" tabindex="-1">13.1 完整提示词库 <a class="header-anchor" href="#_13-1-完整提示词库" aria-label="Permalink to &quot;13.1 完整提示词库&quot;">​</a></h3><ul><li>13.1.1 按任务找：电商、品牌、内容、人物、空间、信息图、插画与视频</li><li>13.1.2 按用途找：分析、策划、生图、修图、排版与批量工作流</li><li>13.1.3 单条模板：完整正文、所需输入、填写示例、输出要求与适配说明</li><li>13.1.4 提示词变体、失败修改与结果状态</li></ul><h3 id="_13-2-案例与源文件库" tabindex="-1">13.2 案例与源文件库 <a class="header-anchor" href="#_13-2-案例与源文件库" aria-label="Permalink to &quot;13.2 案例与源文件库&quot;">​</a></h3><ul><li>13.2.1 按任务与品类查找完整案例</li><li>13.2.2 原始素材、过程截图、结果对照与关键修改</li><li>13.2.3 实测案例、演示方案、未执行模板与失败案例的区分</li><li>13.2.4 可编辑文件、工作流、使用说明与来源</li></ul><h3 id="_13-3-模型与工具导航" tabindex="-1">13.3 模型与工具导航 <a class="header-anchor" href="#_13-3-模型与工具导航" aria-label="Permalink to &quot;13.3 模型与工具导航&quot;">​</a></h3><ul><li>13.3.1 按能力选：生成、文字、多参考、局部编辑、透明与视频</li><li>13.3.2 网站、画布、插件、本地软件与API入口</li><li>13.3.3 准确模型名称、版本、分支与适用条件</li><li>13.3.4 官方文档、操作教程与工具变化记录</li></ul><h3 id="_13-4-开源仓库推荐" tabindex="-1">13.4 开源仓库推荐 <a class="header-anchor" href="#_13-4-开源仓库推荐" aria-label="Permalink to &quot;13.4 开源仓库推荐&quot;">​</a></h3><ul><li>13.4.1 工作流与画布：ComfyUI、InvokeAI与相关扩展</li><li>13.4.2 抠图、背景与修复：rembg、BiRefNet等</li><li>13.4.3 图层编辑与放大：Krita AI Diffusion、Upscayl等</li><li>13.4.4 电商套图、详情页与设计自动化项目</li><li>13.4.5 信息图与可编辑图形：Mermaid、Excalidraw等</li><li>13.4.6 图像／视频模型、官方示例与工作流</li><li>13.4.7 提示词资源库与现有个人玩法库的关联</li><li>13.4.8 每个推荐的说明：用途、适合任务、上手路径、条件、许可与维护状态</li><li>13.4.9 业务流程Skill仓库：鞋类主图、详情页与SKU系列生产等；分别标注输入依赖与验证状态</li></ul><h3 id="_13-5-资料发现、收录与更新" tabindex="-1">13.5 资料发现、收录与更新 <a class="header-anchor" href="#_13-5-资料发现、收录与更新" aria-label="Permalink to &quot;13.5 资料发现、收录与更新&quot;">​</a></h3><ul><li>13.5.1 信源库：官方来源、实践作者、资源目录、讨论与用户线索</li><li>13.5.2 仓库发现：任务词、文件内容、作者项目与引用扩展</li><li>13.5.3 收录资料卡：任务、输入输出、依赖、许可、证据与目录位置</li><li>13.5.4 去重与版本：同一仓库、镜像、改进fork与新进展分别处理</li><li>13.5.5 基础库与近期更新：有用旧方法持续补齐，实际变化另行跟踪</li><li>13.5.6 AIHOT复用：采集、相关性预筛、内容判断、归组与更新整理</li><li>13.5.7 反馈与维护：有效线索、待补内容、失效资源、更新日志与读者反馈</li><li>13.5.8 来源记录与内容复用：一份原件，多个任务入口</li><li>13.5.9 仓库长期维护：内容源、影响定位、贡献、更新记录与失败恢复</li></ul><h2 id="目录组织原则" tabindex="-1">目录组织原则 <a class="header-anchor" href="#目录组织原则" aria-label="Permalink to &quot;目录组织原则&quot;">​</a></h2><ol><li><strong>按作品和任务分类。</strong> “主图、品牌海报、知识卡片”是稳定入口；具体工具与模型放在教程的实现路径和资料卡中。</li><li><strong>通用方法集中维护。</strong> 抠图、蒙版、参考图角色、系列一致性、文字检查集中讲，再链接到电商等专题。</li><li><strong>提示词方法与提示词库分开。</strong> 第02章教写法，第13章提供完整模板；应用专题关联对应模板与案例。</li><li><strong>三类画布分别展开。</strong> 第11章讲操作与组合，第03章放电商完整流程；Codex操作PS在第12章单独讲清。</li><li><strong>案例与资源只存一份。</strong> 同一案例可进入电商、品牌、画布等目录，引用同一份素材、过程和源文件。</li></ol><h2 id="建设顺序建议" tabindex="-1">建设顺序建议 <a class="header-anchor" href="#建设顺序建议" aria-label="Permalink to &quot;建设顺序建议&quot;">​</a></h2><ul><li><strong>第一步，定目录：</strong> 确认上述四组、14章与三级目录，明确现有内容各自归属。</li><li><strong>第二步，补共用基础：</strong> 优先补齐00—02，统一每篇教程的输入、步骤、完整提示词、输出与检查项。</li><li><strong>第三步，分专题建设：</strong> 电商投入最多；品牌、内容、人物、信息图与视频同步建立基础案例，摄影空间和插画逐步补齐。</li><li><strong>第四步，串联制作路径：</strong> 把画布、节点、图层、Codex与批量流程接入具体专题，补齐提示词、案例与仓库导航。</li></ul><p>章节按实际任务逐步补齐；实操案例另记录真实输入、过程和产物。</p><p>实施与贡献请阅读<a href="/ai-visual-creation-handbook/maintenance">维护说明</a>。</p>',72)])])}const b=i(r,[["render",o]]);export{_ as __pageData,b as default};
